import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [a, b, m] = input[0].split(" ").map(BigInt);

// 繰り返し二乗法: B を 2 進数で見て、ビットが立っている桁の A^(2^k) を掛ける
function modPow(base: bigint, exp: bigint, mod: bigint): bigint {
  let result = 1n % mod;
  base %= mod;
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1n;
  }
  return result;
}
console.log(modPow(a, b, m).toString());
